SELECT r.reception_id, r.reception_no, r.patient_id, p.patient_name, r.visit_type, r.department_id, d.department_name, r.doctor_id, doc.doctor_name, r.reservation_id, r.scheduled_at, r.arrived_at, r.status, r.note, r.is_active, r.inactive_at, r.inactive_reason_code, r.inactive_reason_text, r.cancel_reason_code, r.cancel_reason_text, r.hold_reason_code, r.hold_reason_text, r.created_by, r.updated_by, r.created_at, r.updated_at FROM reception r LEFT JOIN patient p ON p.patient_id = r.patient_id LEFT JOIN department d ON d.department_id = r.department_id LEFT JOIN doctor doc ON doc.doctor_id = r.doctor_id
AND r.reception_no = #{searchValue}
AND r.patient_id = #{searchValue}
AND p.patient_name LIKE '%' || #{searchValue} || '%'
AND r.status = #{searchValue}
AND TRUNC(r.created_at) >= TO_DATE(#{dateFrom}, 'YYYY-MM-DD')
AND TRUNC(r.created_at) <= TO_DATE(#{dateTo}, 'YYYY-MM-DD')
AND r.department_id = #{departmentId}
AND r.doctor_id = #{doctorId}
ORDER BY r.reception_id

SELECT r.reception_id, r.reception_no, r.patient_id, p.patient_name, r.visit_type, r.department_id, d.department_name, r.doctor_id, doc.doctor_name, r.reservation_id, r.scheduled_at, r.arrived_at, r.status, r.note, r.is_active, r.inactive_at, r.inactive_reason_code, r.inactive_reason_text, r.cancel_reason_code, r.cancel_reason_text, r.hold_reason_code, r.hold_reason_text, r.created_by, r.updated_by, r.created_at, r.updated_at FROM reception r LEFT JOIN patient p ON p.patient_id = r.patient_id LEFT JOIN department d ON d.department_id = r.department_id LEFT JOIN doctor doc ON doc.doctor_id = r.doctor_id
r.is_active = 1 AND r.status IN ('WAITING', 'CALLED')
AND r.department_id = #{departmentId}
AND r.doctor_id = #{doctorId}
AND TRUNC(r.created_at) = TO_DATE(#{date}, 'YYYY-MM-DD')
ORDER BY CASE WHEN r.scheduled_at IS NULL THEN 1 ELSE 0 END, r.scheduled_at, r.created_at
